"""Independent PDF/UI themes and durable account defaults in a real viewer."""
from tests.viewer_acceptance import PDF, SELECT, viewport, screenshot


def run_appearance(cdp,a,b,fixture,base):
    ev=lambda script:cdp.evaluate(a,script)
    wait=lambda script:cdp.wait(a,script)
    viewport(cdp,a,1280,900)
    wait("document.querySelector('iframe').contentDocument.querySelector('.canvasWrapper canvas')!=null")
    wait("document.querySelector('iframe').contentDocument.querySelector('.textLayer span')!=null")
    ev(SELECT)
    ev("""(async()=>{
      const {captureTextSelection}=await import('/static/review/anchor_selection.js');
      const {createThread}=await import('/static/review/thread_api.js');
      const w=document.querySelector('iframe').contentWindow,c=JSON.parse(document.querySelector('#anchor-config').textContent);
      await createThread(c.threadsUrl,captureTextSelection(w,w.PDFViewerApplication),'Appearance fixture comment');
      w.getSelection().removeAllRanges();
    })()""")
    wait("document.querySelector('iframe').contentDocument.querySelector('.pdf-review-thread-highlight')!=null")
    ev("window.originalHighlightColor=(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.pdf-review-thread-highlight')).backgroundColor;})()")
    ev("window.themeCanvas=document.querySelector('iframe').contentDocument.querySelector('.canvasWrapper canvas');window.themeScale="+PDF+".currentScale")
    assert ev("document.documentElement.dataset.uiTheme==='light'&&document.documentElement.dataset.pdfTheme==='light'&&document.documentElement.dataset.pdfColorAmount==='50'&&document.documentElement.dataset.pdfWhitePoint==='65'")
    ev("document.querySelector('#review-view-menu').open=true;document.querySelector('#review-pdf-dark').click()")
    assert ev("document.querySelector('#review-pdf-dark').getAttribute('aria-checked')==='true'&&document.documentElement.dataset.uiTheme==='light'")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter.includes('invert(0.9)')&&w.document.querySelector('.canvasWrapper canvas')===themeCanvas&&w.PDFViewerApplication.pdfViewer.currentScale===themeScale;})()")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow,s=w.getComputedStyle(w.document.querySelector('.pdf-review-thread-highlight'));return s.filter==='none'&&s.mixBlendMode==='normal'&&s.backgroundColor===originalHighlightColor;})()")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter.includes('grayscale(0.5)');})()")
    screenshot(cdp,a,'pdf-dark-defaults')
    ev("(()=>{const color=document.querySelector('#review-pdf-color');color.value='100';color.dispatchEvent(new Event('input',{bubbles:true}))})()")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter.includes('grayscale(0)');})()")
    ev("(()=>{const color=document.querySelector('#review-pdf-color');color.value='25';color.dispatchEvent(new Event('input',{bubbles:true}));const white=document.querySelector('#review-pdf-white-point');white.value='60';white.dispatchEvent(new Event('input',{bubbles:true}))})()")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return document.querySelector('#review-pdf-colors output[for=review-pdf-white-point]').textContent==='60%'&&w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter.includes('grayscale(0.75)')&&w.document.documentElement.dataset.pdfWhitePoint==='60'&&Math.abs(parseFloat(w.document.documentElement.style.getPropertyValue('--pdf-dark-brightness'))-2/3)<.00001&&w.document.querySelector('.canvasWrapper canvas')===themeCanvas;})()")
    ev("document.querySelector('#review-view-menu').open=true;document.querySelector('#review-pdf-white-point').focus()")
    for kind in ['keyDown','keyUp']:
        cdp.call('Input.dispatchKeyEvent',dict(type=kind,key='ArrowLeft',code='ArrowLeft',windowsVirtualKeyCode=37),a)
    assert ev("document.querySelector('#review-view-menu').open&&!document.querySelector('#review-pdf-colors').hidden&&!document.querySelector('#review-pdf-colors').matches('details')&&document.querySelector('#review-pdf-white-point').value==='59'")
    ev("document.querySelector('#review-pdf-dark').click()")
    assert ev("document.querySelector('#review-view-menu').open&&document.querySelector('#review-pdf-colors').hidden")
    ev("document.querySelector('#review-pdf-dark').click()")
    assert ev("document.querySelector('#review-view-menu').open&&!document.querySelector('#review-pdf-colors').hidden&&document.querySelector('#review-pdf-colors').parentElement===document.querySelector('#review-view-menu > .toolbar-popover')")
    ev("document.querySelector('#review-ui-dark').click()")
    assert ev("document.documentElement.dataset.uiTheme==='dark'&&document.documentElement.dataset.pdfTheme==='dark'&&document.querySelector('#review-ui-dark').getAttribute('aria-checked')==='true'")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.documentElement).colorScheme==='dark'&&w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter.includes('invert(0.9)');})()")
    ev("document.querySelector('#review-ui-dark').click()")
    assert ev("document.documentElement.dataset.uiTheme==='light'&&document.documentElement.dataset.pdfTheme==='dark'")
    cdp.call('Emulation.setEmulatedMedia',{'media':'print'},a)
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter==='none';})()")
    cdp.call('Emulation.setEmulatedMedia',{'media':''},a)
    cdp.call('Page.navigate',{'url':base+'/account'},a)
    wait("document.readyState==='complete'&&document.querySelector('#appearance-form input[name=ui_theme]')!=null")
    assert ev("document.querySelector('#appearance-form button')===null&&document.querySelector('#appearance-form').nextElementSibling.tagName==='SMALL'")
    assert ev("(()=>{const ui=document.querySelector('[name=ui_theme]'),pdf=document.querySelector('[name=pdf_theme]');ui.click();pdf.click();ui.click();ui.click();return document.documentElement.dataset.uiTheme==='dark';})()")
    wait("document.querySelector('#appearance-form').dataset.saving==='false'&&document.querySelector('[name=pdf_theme]').checked")
    ev("(()=>{const color=document.querySelector('[name=pdf_color_amount]');color.value='35';color.dispatchEvent(new Event('input',{bubbles:true}));color.dispatchEvent(new Event('change',{bubbles:true}));const white=document.querySelector('[name=pdf_white_point]');white.value='70';white.dispatchEvent(new Event('input',{bubbles:true}));white.dispatchEvent(new Event('change',{bubbles:true}))})()")
    wait("document.querySelector('#appearance-form').dataset.saving==='false'")
    assert ev("document.querySelector('#appearance-form output[for=account-pdf-white-point]').textContent==='70%'")
    # Failed persistence restores the last saved choice rather than silently
    # leaving a preference that will disappear on the next visit.
    ev("window.appearanceFetch=window.fetch;window.fetch=(url,...args)=>String(url).endsWith('/account/appearance')?Promise.reject(Error('fixture offline')):appearanceFetch(url,...args)")
    assert ev("(()=>{document.querySelector('[name=ui_theme]').click();return document.documentElement.dataset.uiTheme==='light';})()")
    wait("document.querySelector('#appearance-form').dataset.saving==='false'&&!document.querySelector('#appearance-error').hidden")
    assert ev("document.documentElement.dataset.uiTheme==='dark'&&document.querySelector('[name=ui_theme]').checked")
    ev("window.fetch=appearanceFetch;document.querySelector('[name=ui_theme]').click();document.querySelector('[name=ui_theme]').click()")
    wait("document.querySelector('#appearance-form').dataset.saving==='false'&&document.querySelector('#appearance-error').hidden")
    wait("getComputedStyle(document.documentElement).colorScheme==='dark'")
    screenshot(cdp,a,'account-dark-appearance')
    cdp.call('Page.navigate',{'url':base+f"/versions/{fixture['versions'][0]}/view"},a)
    wait("document.querySelector('#realtime-status')?.textContent==='Live'&&document.querySelector('iframe').contentDocument.querySelector('.canvasWrapper canvas')!=null")
    assert ev("document.documentElement.dataset.uiTheme==='dark'&&document.documentElement.dataset.pdfTheme==='dark'&&document.querySelector('#review-pdf-dark').getAttribute('aria-checked')==='true'")
    assert ev("document.documentElement.dataset.pdfColorAmount==='35'&&document.documentElement.dataset.pdfWhitePoint==='70'")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.document.documentElement.dataset.uiTheme==='dark'&&w.document.documentElement.dataset.pdfTheme==='dark'&&w.getComputedStyle(w.document.documentElement).colorScheme==='dark';})()")
    ev("document.querySelector('[data-left-card=search]').click();document.querySelector('#review-pdf-dark').click()")
    wait("document.querySelector('.left-card')!=null")
    assert ev("document.documentElement.dataset.uiTheme==='dark'&&document.documentElement.dataset.pdfTheme==='light'")
    assert ev("(()=>{const w=document.querySelector('iframe').contentWindow;return w.getComputedStyle(w.document.querySelector('.canvasWrapper')).filter==='none';})()")
    screenshot(cdp,a,'viewer-dark-ui-light-pdf')
    ev("document.querySelector('#review-pdf-dark').click()")
    screenshot(cdp,a,'viewer-dark-ui-dark-pdf')
    cdp.call('Page.reload',{},a)
    wait("document.querySelector('#realtime-status')?.textContent==='Live'")
    assert ev("document.documentElement.dataset.pdfTheme==='dark'")
    viewport(cdp,a,390,844)
    screenshot(cdp,a,'viewer-dark-mobile')
    assert ev("document.documentElement.scrollWidth<=innerWidth")
    # Public legal pages follow both temporary viewer choices and saved account
    # appearance without loading account data on those public routes.
    ev("document.querySelector('#review-ui-dark').click()")
    wait("document.cookie.split(';').some(c=>c.trim()==='pdf_review_ui_theme=light')")
    cdp.call('Page.navigate',{'url':base+'/privacy'},a)
    wait("document.readyState==='complete'&&document.querySelector('.legal-policy')!=null")
    assert ev("document.documentElement.dataset.uiTheme==='light'&&getComputedStyle(document.documentElement).colorScheme==='light'")
    cdp.call('Page.navigate',{'url':base+'/account'},a)
    wait("document.readyState==='complete'&&document.documentElement.dataset.uiTheme==='dark'")
    for path in ['/privacy','/tos']:
        cdp.call('Page.navigate',{'url':base+path},a)
        wait("document.readyState==='complete'&&document.querySelector('.legal-policy')!=null")
        assert ev("document.documentElement.dataset.uiTheme==='dark'&&getComputedStyle(document.documentElement).colorScheme==='dark'&&!document.querySelector('meta[name=csrf-token]')")
        assert ev("document.documentElement.scrollWidth<=innerWidth")
    screenshot(cdp,a,'terms-dark-mobile')
    print('PASS independent PDF/UI themes, immediate toggle without canvas rebuild, print colors, saved account defaults, mobile layout',flush=True)
